/* ══ Pricing toggle ═════════════════════════════════
   A pricing card for glitchnobody labs Pro. Flip between Monthly and Yearly:
   the price rolls like an odometer, the billing line changes, and the
   yearly-only perks light up. Three toggle styles, four currencies.

   ── THE MATHS ────────────────────────────────────
   The monthly price is converted to the chosen currency and rounded to a
   whole number. The yearly price per month is that minus the discount,
   rounded again; billed yearly is that times twelve, and the saving is what
   twelve monthly payments would have cost minus it. Intl.NumberFormat writes
   the symbol and the grouping separators.

   ── A STRIP PER DIGIT ────────────────────────
   Every digit is a one-digit-tall window over a strip of 0 to 9 repeated
   five times. A new digit moves the strip with a CSS transform in one fixed
   direction (down when the price drops, up when it rises), wrapping into the
   next copy instead of rolling back. After the roll the strip is quietly
   moved back to the middle copy with transitions off. Each digit gets a
   small delay from the right, and a tick sound on the same timer.

   ── THE TOGGLE ─────────────────────────────
   Segmented and Tabs keep one thumb or underline that slides under the
   active half with a CSS linear() spring. Switch is a single button with
   role=switch. The first two are a radiogroup you can drive with Left and
   Right. A live region reads the new plan out once it has changed. */

import { useEffect, useLayoutEffect, useRef, useState, type CSSProperties, type KeyboardEvent } from "react";
import { Icon } from "@iconify/react";

type Sound = (name: string, o?: { volume?: number; pitch?: number }) => void;
type Plan = "Monthly" | "Yearly";

export type PricingToggleProps = {
  /** monthly price in USD before conversion */
  price?: number;
  /** yearly discount in percent */
  discount?: number;
  currency?: "USD" | "EUR" | "GBP" | "INR";
  toggle?: "Segmented" | "Switch" | "Tabs";
  /** how many feature rows, 2 to 6 */
  features?: number;
  cta?: "Solid" | "Outline";
  /** the plan it starts on */
  plan?: Plan;
  onCheckout?: (plan: Plan) => void;
  sound?: boolean;
  /** 0 to 100 */
  volume?: number;
  onSound?: Sound;
};

