const FEATURES = [
  { icon: "ph:code-bold", name: "Full source", note: "Every line is yours", yearly: false },
  { icon: "ph:speaker-high-bold", name: "Sound files", note: "Every click and pop", yearly: false },
  { icon: "ph:calendar-plus-bold", name: "New every week", note: "Ships every Monday", yearly: false },
  { icon: "ph:lightning-bold", name: "Early access", note: "7 days before all", yearly: true },
  { icon: "ph:copy-bold", name: "Copy prompt", note: "One click to your agent", yearly: false },
  { icon: "ph:infinity-bold", name: "Lifetime updates", note: "Never pay twice", yearly: true },
];

const CUR = {
  USD: { rate: 1, locale: "en-US" },
  EUR: { rate: 0.92, locale: "en-IE" },
  GBP: { rate: 0.79, locale: "en-GB" },
  INR: { rate: 84, locale: "en-IN" },
};

const COPIES = 5;
const HOME = 20;
const STEP = 40; // ms between one rolling digit and the next
const CELLS = Array.from({ length: COPIES * 10 }, (_, i) => <span key={i}>{i % 10}</span>);

/* shortcut: a digit column that appears or disappears mounts or unmounts without animating; upgrade if the width jump matters */
function Digit({ d, dir, delay, onRoll }: { d: number; dir: number; delay: number; onRoll: () => void }) {
  const [idx, setIdx] = useState(HOME + d);
  const [snap, setSnap] = useState(false);
  const cur = useRef(d);
  useLayoutEffect(() => {
    if (cur.current === d) return;
    const from = cur.current;
    cur.current = d;
    const delta = dir >= 0 ? (d - from + 10) % 10 : -((from - d + 10) % 10);
    setSnap(false);
    setIdx((i) => i + delta);
    const t1 = setTimeout(onRoll, delay);
    const t2 = setTimeout(() => {
      setSnap(true);
      setIdx(HOME + cur.current);
    }, delay + 360);
    return () => {
      clearTimeout(t1);
      clearTimeout(t2);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [d]);
  return (
    <span className="pt-digit" aria-hidden="true">
      <span className="pt-strip" data-snap={snap || undefined} style={{ transform: `translateY(${-idx}em)`, transitionDelay: snap ? "0ms" : `${delay}ms` }}>
        {CELLS}
      </span>
    </span>
  );
}

export function PricingToggle({
  price = 24,
  discount = 20,
  currency = "USD",
  toggle = "Segmented",
  features = 4,
  cta = "Solid",
  plan: startPlan = "Monthly",
  onCheckout,
  sound = true,
  volume = 70,
  onSound,
}: PricingToggleProps) {
  const [plan, setPlan] = useState<Plan>(startPlan);
  const [fx, setFx] = useState(false);
  const [oldShown, setOldShown] = useState(false);
  const prev = useRef(plan);
  const dir = useRef(1);
  const lastTick = useRef(0);
  const loud = sound && onSound ? volume / 100 : 0;
  const play = (name: string, v: number, pitch?: number) => {
    if (loud) onSound!(name, { volume: v * loud, pitch });
  };

  const c = CUR[currency];
  const fmt = new Intl.NumberFormat(c.locale, { style: "currency", currency, maximumFractionDigits: 0 });
  const monthly = Math.round(price * c.rate);
  const perMonth = Math.round(monthly * (1 - discount / 100));
  const billed = perMonth * 12;
  const saving = monthly * 12 - billed;
  const yearly = plan === "Yearly";
  const shown = yearly ? perMonth : monthly;
  const text = fmt.format(shown);
  const cells = [...text];
  const rolling = (i: number) => cells.length - 1 - i;

  const choose = (next: Plan) => {
    if (next === plan) return;
    dir.current = next === "Yearly" ? -1 : 1;
    setPlan(next);
    setFx(true);
  };

  /* react to a plan change once: sounds and the struck-through old price */
  useEffect(() => {
    if (prev.current === plan) return;
    prev.current = plan;
    play("tick", 0.5);
    let t1: ReturnType<typeof setTimeout> | undefined;
    let t2: ReturnType<typeof setTimeout> | undefined;
    if (plan === "Yearly") {
      setOldShown(true);
      t1 = setTimeout(() => setOldShown(false), 1200);
      if (FEATURES.slice(0, features).some((f) => f.yearly)) t2 = setTimeout(() => play("pop", 0.45), 120);
    } else setOldShown(false);
    return () => {
      clearTimeout(t1);
      clearTimeout(t2);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [plan]);

  const roll = () => {
    const now = performance.now();
    if (now - lastTick.current < STEP) return;
    lastTick.current = now;
    play("tick", 0.25, 1.2);
  };

  const key = (e: KeyboardEvent) => {
    if (e.key === "ArrowLeft" || e.key === "ArrowUp") choose("Monthly");
    else if (e.key === "ArrowRight" || e.key === "ArrowDown") choose("Yearly");
    else return;
    e.preventDefault();
    const radios = e.currentTarget.querySelectorAll<HTMLElement>("[role=radio]");
    radios[e.key === "ArrowLeft" || e.key === "ArrowUp" ? 0 : 1]?.focus();
  };

  const chip = discount > 0 ? <span className="pt-chip">−{discount}%</span> : null;
  const options = (["Monthly", "Yearly"] as Plan[]).map((p) => (
    <button
      key={p}
      type="button"
      role="radio"
      aria-checked={plan === p}
      tabIndex={plan === p ? 0 : -1}
      className="pt-opt"
      data-on={plan === p}
      onClick={() => choose(p)}
    >
      {p}
      {p === "Yearly" && chip}
    </button>
  ));

  const style = { "--pt-x": yearly ? 1 : 0 } as CSSProperties;
  const live = yearly
    ? `Yearly, ${perMonth} ${currency} a month, billed ${billed} ${currency} yearly`
    : `Monthly, ${monthly} ${currency} a month`;

  return (
    <div className="pt" data-fx={fx || undefined} data-toggle={toggle} data-cta={cta} data-plan={plan} style={style}>
      <div className="pt-head">
        <img className="pt-logo" src={LOGO} alt="" draggable={false} />
        <span className="pt-name">
          glitchnobody labs <span className="pt-pro">Pro</span>
        </span>
      </div>
      <p className="pt-desc">60 small interactive components with sound. Copy the prompt, make it yours.</p>

      {toggle === "Switch" ? (
        <div className="pt-toggle pt-switchrow">
          <span className="pt-side" data-on={!yearly}>Monthly</span>
          <button
            type="button"
            role="switch"
            aria-checked={yearly}
            aria-label="Yearly billing"
            className="pt-switch"
            onClick={() => choose(yearly ? "Monthly" : "Yearly")}
          >
            <span className="pt-knob" />
          </button>
          <span className="pt-side" data-on={yearly}>Yearly{chip}</span>
        </div>
      ) : (
        <div className="pt-toggle pt-group" role="radiogroup" aria-label="Billing period" onKeyDown={key}>
          <span className="pt-thumb" aria-hidden="true" />
          {options}
        </div>
      )}

      <div className="pt-price">
        <span className="pt-amount" aria-hidden="true">
          {cells.map((ch, i) =>
            /\d/.test(ch) ? (
              <Digit key={rolling(i)} d={+ch} dir={dir.current} delay={rolling(i) * STEP} onRoll={roll} />
            ) : (
              <span key={`s${rolling(i)}`} className="pt-sym">{ch}</span>
            )
          )}
        </span>
        <span className="pt-per">/ month</span>
        <span className="pt-old" data-on={oldShown && yearly && discount > 0} aria-hidden="true">{fmt.format(monthly)}</span>
      </div>

      <div className="pt-bill">
        <span className="pt-line" data-on={!yearly}>Billed monthly</span>
        <span className="pt-line" data-on={yearly}>
          <b>{fmt.format(billed)}</b> billed yearly{discount > 0 && ` · save ${fmt.format(saving)}`}
        </span>
      </div>

      <ul className="pt-rows">
        {FEATURES.slice(0, features).map((f) => (
          <li key={f.name} className="pt-row" data-only={f.yearly || undefined} data-on={!f.yearly || yearly}>
            <span className="pt-ico"><Icon icon={f.icon} /></span>
            <span className="pt-fname">{f.name}</span>
            <span className="pt-note">{f.yearly && !yearly ? "Yearly only" : f.note}</span>
          </li>
        ))}
      </ul>

      <button
        type="button"
        className="pt-cta"
        onClick={() => {
          onCheckout?.(plan);
        }}
      >
        Get labs Pro
      </button>
      <p className="pt-fine">Cancel anytime · 14-day refund</p>
      <span className="pt-sr" role="status" aria-live="polite">{fx ? live : ""}</span>
    </div>
  );
}
